// ── Normalise Read File Response ──────────────────────────────────────────
const splitItems = $('Split Out Files').all();

return $input.all().map((item, i) => {
  const rawJson = item.json;
  const content = Array.isArray(rawJson)
    ? (rawJson[0]?.data ?? '')
    : (typeof rawJson === 'string' ? rawJson : (rawJson?.data ?? rawJson?.body ?? ''));
  const filePath = splitItems[i]?.json?.filteredFiles ?? '';
  return { json: { filePath, content } };
});

// ── Clean Completed Tasks ──────────────────────────────────────────────────
const thresholdDays = $('Parse Config').first().json.thresholdDays ?? 14;
const now = new Date();
const cutoff = new Date(now.getTime() - thresholdDays * 24 * 60 * 60 * 1000);

const results = [];

for (const item of $input.all()) {
  const filePath = item.json.filePath ?? '';
  const content = item.json.content ?? '';
  const filename = filePath.split('/').pop() ?? '';

  if (!content) {
    console.log(`⚠️ Skipping file with no content: ${filePath}`);
    results.push({ json: { filePath, content: '', tasksRemoved: [], writeStatus: 'skipped-no-content', writeNeeded: false } });
    continue;
  }

  const isTargetType = /^(Project|Area|Research)\s*[\u2013-]/.test(filename);

  if (!isTargetType) {
    results.push({ json: { filePath, content, tasksRemoved: [], writeStatus: 'skipped-type', writeNeeded: false } });
    continue;
  }

  try {
    const lines = content.split('\n');
    const tasksRemoved = [];
    const keptLines = lines.filter(line => {
      const match = line.match(/^- \[x\].*\u2705\s*(\d{4}-\d{2}-\d{2})/);
      if (!match) return true;
      const taskDate = new Date(match[1]);
      if (taskDate < cutoff) {
        tasksRemoved.push(line.trim());
        return false;
      }
      return true;
    });

    const updatedContent = keptLines.join('\n');
    const writeNeeded = tasksRemoved.length > 0;

    console.log(`${filename}: ${tasksRemoved.length} task(s) removed`);

    results.push({ json: { filePath, content: updatedContent, tasksRemoved, writeStatus: writeNeeded ? 'pending' : 'skipped', writeNeeded } });
  } catch (err) {
    console.error(`❌ Error processing ${filename}: ${err.message}`);
    results.push({ json: { filePath, content: '', tasksRemoved: [], writeStatus: `error-${err.message.slice(0, 30)}`, writeNeeded: false } });
  }
}

return results;

// ── Weekly Master: Build Outputs ─────────────────────────────────────────────
const now = new Date();
// Log time in Auckland local time (NZDT/NZST handled by the timezone)
const nzDate = now.toLocaleString('sv-SE', { timeZone: 'Pacific/Auckland' });
const datestamp = nzDate.slice(0, 16).replace(' ', ' | ');
const runFinishedIso = new Date().toISOString();

const cutoff = new Date(now.getTime() - 60 * 24 * 60 * 60 * 1000);

const controlData = $('Parse Config').first().json;
const lastRunRead = controlData.lastRun;
const controlContent = controlData.controlFileContent ?? '';

const allItems = $('Aggregate Results').first().json.data ?? [];
const fileCount = allItems.length;

const removedLines = [];

for (const item of allItems) {
  const name = item.filePath?.split('/').pop() ?? item.filePath ?? 'unknown';
  const tasksRemoved = item.tasksRemoved ?? [];
  const writeStatus = item.writeStatus ?? 'unknown';

  if (tasksRemoved.length > 0) {
    removedLines.push(`- \`${name}\` — ${tasksRemoved.length} task(s) removed`);
    for (const task of tasksRemoved) {
      removedLines.push(`  - ${task}`);
    }
    if (writeStatus !== 'written' && writeStatus !== 'skipped') {
      removedLines.push(`  ⚠️ Write status: ${writeStatus}`);
    }
  }
}

const removedSection = removedLines.length > 0 ? `\n#### Tasks Removed\n${removedLines.join('\n')}` : '';
const noActivity = removedLines.length === 0 ? '\n*No tasks removed this run.*' : '';

const newEntry = `### ${datestamp}\n**Last run read:** ${lastRunRead}\n**Files scanned:** ${fileCount}${removedSection}${noActivity}`;

const existingLog = $input.item.json.body ?? $input.item.json.data ?? '';
const logSectionMatch = existingLog.match(/^(---[\s\S]*?## Log\n)([\s\S]*)$/m);
const logHeader       = logSectionMatch ? logSectionMatch[1] : existingLog;
const logEntries      = logSectionMatch ? logSectionMatch[2] : '';

const entryBlocks = logEntries.split(/(?=^### \d{4}-\d{2}-\d{2})/m).filter(e => e.trim());
const recentEntries = entryBlocks.filter(block => {
  const dateMatch = block.match(/^### (\d{4}-\d{2}-\d{2})/);
  if (!dateMatch) return true;
  return new Date(dateMatch[1]) >= cutoff;
});

const updatedLog = `${logHeader}\n${[newEntry.trimEnd(), ...recentEntries.map(e => e.trimEnd())].join('\n\n')}\n`;

const updatedControl = controlContent.replace(/\*\*Last run:\*\*\s*[^\n]*/, `**Last run:** ${runFinishedIso}`);

return [{
  updatedLog,
  updatedControl,
  logChanged: updatedLog !== existingLog,
  controlChanged: true
}];

// ── Parse Config ───────────────────────────────────────────────────
const content = $input.item.json.body ?? $input.item.json.data ?? '';
const vaultPath = $('Config').item.json.vaultPath.replace(/\/$/, '');

const lastRunMatch = content.match(/\*\*Last run:\*\*\s*([^\n]+)/);
const lastRunRaw = lastRunMatch ? lastRunMatch[1].trim() : '—';
const oneYearAgo = new Date(Date.now() - 365 * 24 * 60 * 60 * 1000).toISOString();
const lastRunIso = (lastRunRaw === '—' || lastRunRaw === '-' || lastRunRaw === '')
  ? oneYearAgo
  : (isNaN(new Date(lastRunRaw)) ? oneYearAgo : new Date(lastRunRaw).toISOString());

const thresholdMatch = content.match(/\*\*Completed task threshold \(days\):\*\*\s*`?(\d+)`?/);
const thresholdDays = thresholdMatch ? parseInt(thresholdMatch[1], 10) : 14;

const targetSection = content.match(/\*\*Target paths?:\*\*([\s\S]*?)(?=\n\*\*|\n---|\n##|$)/);
const targetRaw = targetSection ? targetSection[1] : '';
const targetPaths = [...targetRaw.matchAll(/^- `?([^`\n]+)`?/gm)]
  .map(m => m[1].trim())
  .filter(p => p.length > 0);

const resolvedTargetPaths = targetPaths.length > 0
  ? targetPaths
  : ($('Config').item.json.targetPaths ?? 'Projects').split(',').map(p => p.trim());

const absoluteTargetPaths = resolvedTargetPaths.map(p => `${vaultPath}/${p}`);

const excludedSection = content.match(/\*\*Excluded paths?:\*\*([\s\S]*?)(?=\n\*\*|\n---|\n##|$)/);
const excludedRaw = excludedSection ? excludedSection[1] : '';
const excludedPaths = [...excludedRaw.matchAll(/^- `?([^`\n]+)`?/gm)]
  .map(m => m[1].trim())
  .filter(p => p.length > 0);

const resolvedExcludedPaths = excludedPaths.length > 0
  ? excludedPaths
  : ($('Config').item.json.excludedPaths ?? '').split(',').map(p => p.trim()).filter(Boolean);

console.log(`Target paths: ${resolvedTargetPaths.join(', ')}`);
console.log(`Excluded paths: ${resolvedExcludedPaths.join(', ')}`);
console.log(`Threshold: ${thresholdDays} days`);
console.log(`Last run: ${lastRunRaw}`);

return [{
  controlFileContent: content,
  lastRun: lastRunRaw,
  lastRunIso,
  targetPaths: resolvedTargetPaths,
  absoluteTargetPaths,
  excludedPaths: resolvedExcludedPaths,
  thresholdDays
}];

// ── Filter & Parse File List (Weekly) ──────────────────────────────────────
const vaultPath = $('Config').item.json.vaultPath;
const excludedPaths = $('Parse Config').item.json.excludedPaths ?? [];
const stdout = $input.item.json.stdout ?? '';

const absolutePaths = stdout.split('\n').map(l => l.trim()).filter(l => l.length > 0);

const relativePaths = absolutePaths.map(p => {
  const prefix = vaultPath.endsWith('/') ? vaultPath : vaultPath + '/';
  const rel = p.startsWith(prefix) ? p.slice(prefix.length) : p;
  return rel.replace(/^\.\//,  '');
});

const filtered = relativePaths.filter(filePath =>
  !excludedPaths.some(excluded => filePath.startsWith(excluded))
);

console.log(`Total .md files found: ${relativePaths.length}`);
console.log(`After exclusion filter: ${filtered.length}`);

return [{
  allFiles: relativePaths,
  filteredFiles: filtered,
  excludedCount: relativePaths.length - filtered.length,
  fileCount: filtered.length
}];
